let internalDebugging = false
let traceWidth = 78

// ---------------------------------------------------------------------------

export const traceInternalDebugging = (
		debugFlag = true
		): void => {

	internalDebugging = debugFlag
	if (debugFlag) {
		LOG("turn on internal debugging in trace.lib.civet")
	}
	else {
		LOG("turn off internal debugging in trace.lib.civet")
	}
	return
}

// ---------------------------------------------------------------------------

export const stack = new CCallStack()

type TFuncDesc = {
	funcName: string
	plus: boolean
	}

// --- Comes from call to setTracing()
let lFuncList: TFuncDesc[] = []

type TLogFuncMult = (
	level: number,
	funcName: string,
	lValues: unknown[]
	) => void

type TLogFuncOne = (
	level: number,
	funcName: string,
	lValues: unknown
	) => void

type TLogFuncNone = (
	level: number,
	funcName: string,
	) => void

type TLogValue = (
	level: number,
	value: unknown,
	label: string
	) => void

type TLogFunc = TLogFuncMult | TLogFuncOne | TLogFuncNone | TLogValue

let traceAll = false   // --- if true, always log
let traceNone = false  // --- if true, never log

// ---------------------------------------------------------------------------

export const setTracing = (
		traceWhat: boolean | string | string[]
		): void => {

	// --- traceWhat can be:
	//        1. a boolean (false = disable, true = debug all)
	//        2. a string (name of a function)
	//        3. an array of strings (names of functions)

	if (internalDebugging) {
		LOG(`setTracing ${OL(traceWhat)}`)
	}

	resetTracing()

	// --- process traceWhat
	switch(jsType(traceWhat)) {
		case 'boolean': {
			if (traceWhat) {
				if (internalDebugging) {
					LOG("set traceAll")
				}
				traceAll = true
			}
			else {
				if (internalDebugging) {
					LOG("set traceNone")
				}
				traceNone = true
			};break;
		}
		case 'string':case 'array': {
			if (internalDebugging) {
				LOG(`traceWhat is ${OL(traceWhat)}`)
			}
			obviously((typeof traceWhat === 'string') || isArray(traceWhat))
			lFuncList = getFuncList(traceWhat);break;
		}
		default: {
			croak(`Bad arg 1: ${OL(traceWhat)}`)
		}
	}

	if (internalDebugging) {
		dumpFuncList()
	}
	return
}

// ---------------------------------------------------------------------------

export const resetTracing = () => {

	// --- reset everything
	stack.reset()
	lFuncList = []
	traceAll = false
	traceNone = false
	clearLog()
	return
}

// ---------------------------------------------------------------------------
// ---------------------------------------------------------------------------

export const getFuncList = (
		funcs: string | string[]
		): TFuncDesc[] => {

	const lFuncs: TFuncDesc[] = []    // return value

	// --- Allow passing in an array of strings
	if (isArray(funcs)) {
		for (const str of funcs) {
			const lItems = getFuncList(str)   // recursive call
			lFuncs.push(...lItems)
		}
	}
	else {
		for (const word of words(funcs)) {
			const [funcName, modifier] = parseFuncStr(word)
			assert(defined(funcName), `Bad debug object: ${OL(word)}`)
			lFuncs.push({
				funcName,
				plus: (modifier === '+')
				})
		}
	}
	return lFuncs
}

// ---------------------------------------------------------------------------
// Stack is only modified in these 8 functions (it is reset in setTracing())
// ---------------------------------------------------------------------------

export const trEnter = (
		funcName: string,
		lArgs: unknown[] = []
		): void => {

	const isTracing = isTracingFunc(funcName)
	if (internalDebugging) {
		LOG(`trEnter ${funcName} ${OL(lArgs)}`)
		LOG(`   - isTracing = ${OL(isTracing)}`)
	}

	if (isTracing) {
		logEnter(stack.logLevel, funcName, lArgs)
	}
	stack.enter(funcName, lArgs, isTracing)
	return
}

// ---------------------------------------------------------------------------

export const trReturn = (
		funcName: string,
		val: (unknown | undefined) = undef
		): void => {

	assert((funcName === stack.curFuncName),
		`trReturn(${funcName}) but cur func is ${stack.curFuncName}`)
	const isTracing = isTracingFunc(funcName)
	if (internalDebugging) {
		LOG(`trReturn ${OL(funcName)}`)
		LOG(`   - isTracing = ${OL(isTracing)}`)
	}

	if (isTracing) {
		const level = stack.logLevel
		logReturn(level, funcName, val)
	}
	stack.returnFrom(funcName, val)
	return
}

// ---------------------------------------------------------------------------

export const trYieldFrom = (
		funcName: string,
		val: (unknown | undefined)
		): void => {

	const isTracing = isTracingFunc(funcName)
	if (internalDebugging) {
		LOG(`trYieldFrom ${OL(funcName)} ${OL(val)}`)
		LOG(`   - isTracing = ${OL(isTracing)}`)
	}

	if (isTracing) {
		const level = stack.logLevel
		logYield(level, funcName, val)
	}
	stack.yieldFrom(funcName, val)
	return
}

// ---------------------------------------------------------------------------

export const trResume = (
		funcName: string
		): void => {

	const isTracing = isTracingFunc(funcName)
	if (internalDebugging) {
		LOG(`trResume ${OL(funcName)}`)
		LOG(`   - isTracing = ${OL(isTracing)}`)
	}

	stack.resume(funcName)
	if (isTracing) {
		const level = stack.logLevel
		logResume(level-1, funcName)
	}
	return
}

// ---------------------------------------------------------------------------

export const tr = (
		val: unknown,
		label: string = ''
		): void => {

	const isTracing = isTracingFunc(stack.curFuncName)
	if (internalDebugging) {
		LOG(`tr ${OL(val)}, ${OL(label)}`)
		LOG(`   - isTracing = ${OL(isTracing)}`)
	}

	if (isTracing) {
		const level = stack.logLevel
		logValue(level, val, label)
	}
	return
}

// ---------------------------------------------------------------------------

export const isTracingFunc = (
		funcName: string
		): boolean => {

	if (traceNone) {
		return false
	}
	if (traceAll) {
		return true
	}

	// --- funcName came from a call to trEnter()
	//     it might be of form <object>.<method>
	// --- We KNOW that funcName is active!

	if (internalDebugging) {
		LOG(`isTracingFunc(${OL(funcName)})`)
		LOG(lFuncList)
		stack.dumpStack()
	}

	const lParts = funcName.split('.')

	for (const h of lFuncList) {
		if (h.funcName === funcName) {
			if (internalDebugging) {
				LOG(`   - TRUE - ${OL(funcName)} is in lFuncList`)
			}
			return true
		}
		if (h.plus && stack.isActive(h.funcName)) {
			if (internalDebugging) {
				LOG(`   - TRUE - ${OL(h.funcName)} is active`)
			}
			return true
		}
	}

	if (lParts.length === 2) {   // --- came from trEnter()
		const methodName = lParts[1]
		for (const h of lFuncList) {
			if (h.funcName === methodName) {
				if (internalDebugging) {
					LOG(`   - TRUE - ${OL(methodName)} is in lFuncList`)
				}
				return true
			}
		}
	}
	if (internalDebugging) {
		LOG("   - FALSE")
	}
	return false
}

// ---------------------------------------------------------------------------
// ---------------------------------------------------------------------------
//    Only these 8 functions ever call LOG or LOGVALUE

export const logEnter: TLogFuncMult = (
		level: integer,
		funcName: string,
		lArgs: unknown[]
		): void => {

	const labelPre = getPrefix(level, 'plain')
	if (lArgs.length === 0) {
		LOG(labelPre + `enter ${funcName}`)
	}
	else {
		const str = `enter ${funcName} ${OL(lArgs)}`
		if (stringFits(`${labelPre}${str}`, traceWidth)) {
			LOG(labelPre + str)
		}
		else {
			LOG(labelPre + `enter ${funcName}`)
			let i1 = 0;for (const arg of lArgs) {const i = i1++;
				LOGVALUE(arg, {
						label: `arg[${i}]`,
						prefix: getPrefix(level+1, 'plain'),
						itemPrefix: getPrefix(level+2, 'noLastVbar'),
						short: false
						})
			}
		}
	}
	return
}

// ---------------------------------------------------------------------------

export const logReturn: TLogFuncOne = (
		level: integer,
		funcName: string,
		val: unknown
		): void => {

	const labelPre = getPrefix(level, 'withArrow')
	const str = `return ${OL(val)} from ${funcName}`
	if (stringFits(str, traceWidth)) {
		LOG(labelPre + str)
	}
	else {
		LOG(labelPre + `return from ${funcName}`)
		LOGVALUE(val, {
			label: 'val',
			prefix: getPrefix(level, 'noLastVbar'),
			itemPrefix: getPrefix(level, 'noLastVbar'),
			short: false
			})
	}
	return
}

// ---------------------------------------------------------------------------

export const logYield: TLogFuncOne = (
		level: integer,
		funcName: string,
		val: unknown
		): void => {

	const labelPre = getPrefix(level, 'withYield')
	const str = `yield from ${funcName}: ${OL(val)}`
	if (stringFits(str, traceWidth)) {
		LOG(labelPre + str)
	}
	else {
		LOGVALUE(val, {
			prefix: getPrefix(level, 'plain'),
			itemPrefix: getPrefix(level, 'plain')
			})
	}
	return
}

// ---------------------------------------------------------------------------

export const logResume: TLogFuncNone = (
		level: integer,
		funcName: string,
		): void => {

	assert(isInteger(level), "level not an integer")
	const labelPre = getPrefix(level+1, 'withResume')
	LOG(labelPre + "resume")
	return
}

// ---------------------------------------------------------------------------

export const logValue: TLogValue = (
		level: integer,
		val: unknown,
		label: string = ''
		): void => {

	LOGVALUE(val, {
		label,
		prefix: getPrefix(level, 'plain')
		})
	return
}

// ---------------------------------------------------------------------------

export const parseFuncStr = (str: string): [string, string] => {
	// --- returns [fullName, modifier]

	const lMatches = str.match(/^([A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z_][A-Za-z0-9_]*)?)(\+)?$/)
	assert(defined(lMatches), "Bad func desc: ${OL(str)}")
	const [_, fullName, modifier] = lMatches
	return [fullName, modifier]
}

// ---------------------------------------------------------------------------

export const dumpFuncList = () => {

	LOG('lFuncList: --------------------------------')
	LOG(nice(lFuncList))
	LOG('-------------------------------------------')
	return
}

// ---------------------------------------------------------------------------

export var LOGVALUE = (
		value: unknown,
		hOptions: hash = {}
		): void => {

	// --- Allow label to be empty, i.e. ''

	type opt = {
		prefix: string
		short: boolean
		oneIndent: string
		label: string
		}
	const {prefix, short, oneIndent, label} = getOptions<opt>(hOptions, {
		prefix: '',
		short: false,      // prefer short strings, e.g. 'HASH', 'ARRAY'
		oneIndent: '\t',
		label: ''
		})

	if (internalDebugging) {
		const str1 = OL(value)
		const str2 = OL(label)
		const str3 = OL(prefix)
		LOG(`CALL LOGVALUE(${str1}, label=${str2}), prefix=${str3}`)
	}

	const labelStr = defined(label) ? `${label} = ` : ''

	const jsTyp = jsType(value)

	// --- Handle certain values which should fit, unless
	//     indentation is very deep, but we'll keep it on one line
	//     in any case

	const olStr = `${prefix}${labelStr}${OL(value)}`
	if (isShortVal(jsTyp) || stringFits(olStr, traceWidth)) {
		if (internalDebugging) {
			LOG(`Using OL(), ${olStr.length} <= ${logWidth}`)
		}
		LOG(olStr)
		return
	}

	if (short) {
		if (jsTyp === 'array') {
			LOG(`${prefix}${labelStr}ARRAY`)
			return
		}
		if (jsTyp === 'hash') {
			LOG(`${prefix}${labelStr}HASH`)
			return
		}
		if (jsTyp === 'function') {
			LOG(`${prefix}${labelStr}FUNCTION`)
			return
		}
	}

	const itemPrefix = prefix + oneIndent

	// --- We know now that OL(value) doesn't fit
	//     and all "short values" have been checked already
	switch(jsTyp) {
		case 'string': {
			obviously((typeof value === 'string'))
			LOG(`${prefix}${labelStr}\"\"\"`)
			for (const line of blockToArray(value)) {
				LOG(`${itemPrefix}${line}\n			LOG `)
			};break;
		}//{itemPrefix}\"\"\""

		case 'hash': {
			const str = nice(value, {
				sortKeys: true,
				oneIndent: spaces(3)
				})
			if (labelStr) {
				LOG(`${prefix}${labelStr}`)
			}
			for (const s in blockToArray(str)) {
				LOG(`${itemPrefix}${s}`)
			};break;
		}

		case 'array': {
			const str = nice(value, {
				sortKeys: true,
				oneIndent: spaces(3)
				})
			if (labelStr) {
				LOG(`${prefix}${labelStr}`)
			}
			for (const s in blockToArray(str)) {
				LOG(`${itemPrefix}${s}`)
			};break;
		}

		case 'function': {
			LOG(`${prefix}${labelStr}<function>`);break;
		}

		case 'object': {
			const str = nice(value)
			if (str.includes("\n")) {
				if (labelStr) {
					LOG(`${prefix}${labelStr}`)
				}
				for (const line in blockToArray(str)) {
					LOG(`${itemPrefix}${line}`)
				}
			}
			else {
				LOG(`${prefix}${labelStr}${str}`)
			};break;
		}
	}
	return
}

// ---------------------------------------------------------------------------

const isShortVal = (typ: string) => {

	return words('undef null boolean integer float bigint symbol',
	             'NaN inf neginf null regexp').includes(typ)
}

// ---------------------------------------------------------------------------

export const shortStr = (
		value: unknown,
		typ: string = jsType(value),
		maxLen: number = 32
		): string => {

	if (isShortVal(typ)) {
		return OL(value)
	}
	switch(typ) {
		case 'string': {
			obviously((typeof value === 'string'))
			const len = value.length
			return (
				  (len <= maxLen)
				? value
				: value.substring(0, len - 3) + '...'
				)
		}

		case 'hash': { return 'HASH'
		}
		case 'array': { return 'ARRAY'
		}
		case 'set': { return 'SET'
		}
		case 'map': { return 'MAP'
		}
		case 'iterator': { return 'ITERATOR'
		}
		case 'asyncIterator': { return 'ASYNC ITERATOR'
		}
		case 'class': { return 'CLASS'
		}
		case 'generator': { return 'GENERATOR'
		}
		case 'asyncGenerator': { return 'ASYNC GENERATOR'
		}
		case 'plainFunction': { return 'FUNCTION'
		}
		default: { croak(`Unknown value type: ${OL(value)}`) }
	}
}

